35	/**
36	 * @brief Loading data elements from AXI master to stream.
37	 *
38	 * This module requires the data elements to align to its size in buffer.
39	 * In another word, the start offset is specified by element count from
40	 * the beginning of a vector of AXI port width.
41	 *
42	 * This primitive assumes the width of AXI port is positive integer
43	 * multiple of data element's alignment width.
44	 *
45	 * The alignment width is assumed to be multiple of 8-bit char.
46	 * The AXI master port width is power of two, and no less than 8.
47	 *
48	 * @tparam _BurstLen burst length of AXI buffer, default is 32.
49	 * @tparam _WAxi width of AXI port, must be power of 2 and between 8 to 512.
50	 * @tparam _TStrm stream's type, e.g. ap_uint<aligned_width> for a aligned_width
51	 * stream.
52	 *
53	 * @param rbuf input AXI port.
54	 * @param num number of data elements to load from AXI port.
55	 * @param ostrm output stream.
56	 * @param e_ostrm end flag for output stream.
57	 */
58	/* TODO
59	 * \rst
60	 * ::
61	 *
62	 *    +--------------------------------------------------------+
63	 *    | DDR  -> AXI_BUS  -> FIFO     -> stream(aligned to 16b) |
64	 *    | XXaa    XXaabbcc    XXaabbcc    aa                     |
65	 *    | bbcc    ddXX0000    ddXX0000    bb                     |
66	 *    | ddXX                            cc                     |
67	 *    |                                 dd                     |
68	 *    +--------------------------------------------------------+
69	 *
70	 * \endrst
71	 *
72	 * Add param offset_num offset from the beginning of the buffer, by num of element.
73	 */
74	
75	template <int _BurstLen = 32, int _WAxi, typename _TStrm>
76	void axiToStream(ap_uint<_WAxi>* rbuf, const int num, hls::stream<_TStrm>& ostrm, hls::stream<bool>& e_ostrm);
77	
78	/**
79	 * @brief Loading char data from AXI master to stream.
80	 *
81	 * This primitive relaxes the alignment requirement, and actually load data by
82	 * 8-bit char. The 8-bit chars are packed as output stream wide word.
83	 * The last word may contain invalid data in high-bits if enough char has
84	 * already been packed.
85	 *
86	 * The alignment width is assumed to be multiple of 8-bit char.
87	 * The AXI master port width is power of two, and no less than 8.
88	 *
89	 * \rst
90	 * ::
91	 *
92	 *    +-----------------------------------------------------------------+
93	 *    | DDR  -> AXI_BUS                           -> FIFO     -> stream |
94	 *    | XXX1    XXX1234567812345_6781234567812345    XXX12345    1234   |
95	 *    | ...     ...                                  67812345    5678   |
96	 *    |                                              ...         ...    |
97	 *    | 32XX    6780000321XXXXXX_XXXXXXXXXXXXXXXX    21XXXXXX    21XX   |
98	 *    +-----------------------------------------------------------------+
99	 *
100	 * \endrst
101	 *
102	 * @tparam _BurstLen burst length of AXI buffer, default is 32.
103	 * @tparam _WAxi width of AXI port, must be power of 2 and between 8 to 512.
104	 * @tparam _TStrm stream's type.
105	 *
106	 * @param rbuf input AXI port.
107	 * @param ostrm output stream.
108	 * @param e_ostrm end flag for output stream.
109	 * @param len number of char to load from AXI port.
110	 * @param offset offset from the beginning of the buffer, in number of char.
111	 */
112	template <int _BurstLen = 32, int _WAxi, typename _TStrm>
113	void axiToCharStream(
114	    ap_uint<_WAxi>* rbuf, hls::stream<_TStrm>& ostrm, hls::stream<bool>& e_ostrm, const int len, const int offset = 0);
115	
116	/**
117	 * @brief Loading data elements from AXI master to stream.
118	 *
119	 * This module requires the data elements to align to its size in buffer.
120	 * In another word, the start offset is specified by element count from
121	 * the beginning of a vector of AXI port width.
122	 *
123	 * This primitive assumes the width of AXI port is positive integer
124	 * multiple of data element's alignment width.
125	 *
126	 * The alignment width is assumed to be multiple of 8-bit char.
127	 * The AXI master port width is power of two, and no less than 8.
128	 *
129	 * @tparam _BurstLen burst length of AXI buffer, default is 32.
130	 * @tparam _WAxi width of AXI port, must be power of 2 and between 8 to 512.
131	 * @tparam _TStrm stream's type, e.g. ap_uint<aligned_width> for a aligned_width
132	 * stream.
133	 *
134	 * @param rbuf input AXI port.
135	 * @param num number of data elements to load from AXI port.
136	 * @param ostrm output stream.
137	 * @param e_ostrm end flag for output stream.
138	 */
139	/* TODO
140	 * \rst
141	 * ::
142	 *
143	 *    +--------------------------------------------------------+
144	 *    | DDR  -> AXI_BUS  -> FIFO     -> stream(aligned to 16b) |
145	 *    | XXaa    XXaabbcc    XXaabbcc    aa                     |
146	 *    | bbcc    ddXX0000    ddXX0000    bb                     |
147	 *    | ddXX                            cc                     |
148	 *    |                                 dd                     |
149	 *    +--------------------------------------------------------+
150	 *
151	 * \endrst
152	 *
153	 * Add param offset_num offset from the beginning of the buffer, by num of element.
154	 */
155	
156	template <int _BurstLen = 32, int _WAxi, typename _TStrm>
157	void axiToStream(ap_uint<_WAxi>* rbuf, const int num, hls::stream<_TStrm>& ostrm);
158	
159	// ------------------- Implementation --------------------------
160	
161	namespace details {
162	
163	template <int _WAxi, int _BurstLen>
164	void read_to_vec(ap_uint<_WAxi>* vec_ptr, const int nrow, const int scal_vec, hls::stream<ap_uint<_WAxi> >& vec_strm) {
165	    const int nread = (nrow + scal_vec - 1) / scal_vec;
166	READ_TO_VEC:
167	    for (int i = 0; i < nread; ++i) {
168	#pragma HLS loop_tripcount min = 1 max = 1
169	#pragma HLS PIPELINE II = 1
170	        vec_strm.write(vec_ptr[i]);
171	    } // This pipeline must be no judgment, otherwise the tool will not be able
172	      // to derive the correct burst_len
173	}
174	
175	template <int _WAxi, typename _TStrm, int scal_vec>
176	void split_vec(hls::stream<ap_uint<_WAxi> >& vec_strm,
177	               const int nrow,
178	               const int offset_AL,
179	               hls::stream<_TStrm>& r_strm,
180	               hls::stream<bool>& e_strm) {
181	    const int WStrm = 8 * sizeof(_TStrm);
182	    ap_uint<_WAxi> fst_vec = vec_strm.read();
183	    int fst_n = (scal_vec - offset_AL) > nrow ? (nrow + offset_AL) : scal_vec;
184	
185	SPLIT_FEW_VEC:
186	    for (int j = 0; j < scal_vec; ++j) {
187	#pragma HLS loop_tripcount min = 1 max = 1
188	#pragma HLS PIPELINE II = 1
189	        ap_uint<WStrm> fst_r0 = fst_vec.range(WStrm * (j + 1) - 1, WStrm * j);
190	        if (j < fst_n && j >= offset_AL) {
191	            r_strm.write((_TStrm)fst_r0);
192	            e_strm.write(false);
193	        }
194	    }
195	
196	SPLIT_VEC:
197	    for (int i = scal_vec - offset_AL; i < nrow; i += scal_vec) {
198	#pragma HLS loop_tripcount min = 1 max = 1
199	#pragma HLS PIPELINE II = scal_vec
200	        ap_uint<_WAxi> vec = vec_strm.read();
201	        int n = (i + scal_vec) > nrow ? (nrow - i) : scal_vec;
202	
203	        for (int j = 0; j < scal_vec; ++j) {
204	#pragma HLS PIPELINE II = 1
205	            ap_uint<WStrm> r0 = vec.range(WStrm * (j + 1) - 1, WStrm * j);
206	            if (j < n) {
207	                r_strm.write((_TStrm)r0);
208	                e_strm.write(false);
209	            }
210	        }
211	    }
212	    e_strm.write(true);
213	}
214	
215	template <int _WAxi, typename _TStrm, int scal_vec>
216	void split_vec(hls::stream<ap_uint<_WAxi> >& vec_strm,
217	               const int nrow,
218	               const int offset_AL,
219	               hls::stream<_TStrm>& r_strm) {
220	    const int WStrm = 8 * sizeof(_TStrm);
221	    ap_uint<_WAxi> fst_vec = vec_strm.read();
222	    int fst_n = (scal_vec - offset_AL) > nrow ? (nrow + offset_AL) : scal_vec;
223	
224	SPLIT_FEW_VEC:
225	    for (int j = 0; j < scal_vec; ++j) {
226	#pragma HLS loop_tripcount min = 1 max = 1
227	#pragma HLS PIPELINE II = 1
228	        ap_uint<WStrm> fst_r0 = fst_vec.range(_WAxi - 1, WStrm * j);
229	        if (j < fst_n && j >= offset_AL) {
230	            r_strm.write((_TStrm)fst_r0);
231	        }
232	    }
233	
234	SPLIT_VEC:
235	    for (int i = scal_vec - offset_AL; i < nrow; i += scal_vec) {
236	#pragma HLS loop_tripcount min = 1 max = 1
237	#pragma HLS PIPELINE II = scal_vec
238	        ap_uint<_WAxi> vec = vec_strm.read();
239	        int n = (i + scal_vec) > nrow ? (nrow - i) : scal_vec;
240	
241	        for (int j = 0; j < scal_vec; ++j) {
242	            ap_uint<WStrm> r0 = vec.range(_WAxi - 1, WStrm * j);
243	            if (j < n) {
244	                r_strm.write((_TStrm)r0);
245	            }
246	        }
247	    }
248	}
