250	template <int _WAxi, int _BurstLen>
251	void read_to_vec(ap_uint<_WAxi>* vec_ptr,
252	                 const int len,
253	                 const int scal_char,
254	                 const int offset,
255	                 hls::stream<ap_uint<_WAxi> >& vec_strm) {
256	    const int nread = (len + offset + scal_char - 1) / scal_char;
257	
258	READ_TO_VEC:
259	    for (int i = 0; i < nread; ++i) {
260	#pragma HLS loop_tripcount min = 1 max = 1
261	#pragma HLS PIPELINE II = 1
262	        vec_strm.write(vec_ptr[i]);
263	    } // This pipeline must be no judgment, otherwise the tool will not be able
264	      // to derive the correct burst_len
265	}
266	
267	template <int _WAxi, typename _TStrm, int scal_vec>
268	void split_vec_to_aligned(hls::stream<ap_uint<_WAxi> >& vec_strm,
269	                          const int len,
270	                          const int scal_char,
271	                          const int offset,
272	                          hls::stream<_TStrm>& r_strm,
273	                          hls::stream<bool>& e_strm) {
274	    const int nread = (len + offset + scal_char - 1) / scal_char;
275	    // n read times except the first read, n_read+1 = total read times
276	    int cnt_r = nread - 1;
277	    const int nwrite = (len + sizeof(_TStrm) - 1) / sizeof(_TStrm);
278	    const int WStrm = 8 * sizeof(_TStrm);
279	    // first read is specific
280	    ap_uint<_WAxi> vec_reg = vec_strm.read();
281	    ap_uint<_WAxi> vec_aligned = 0;
282	
283	    if (offset) {
284	    LOOP_SPLIT_VEC_TO_ALIGNED:
285	        for (int i = 0; i < nwrite; i += scal_vec) {
286	#pragma HLS loop_tripcount min = 1 max = 1
287	#pragma HLS PIPELINE II = scal_vec
288	            vec_aligned(((scal_char - offset) << 3) - 1, 0) = vec_reg((scal_char << 3) - 1, offset << 3);
289	            if ((scal_char - offset) < len && (cnt_r != 0)) { // always need read
290	                                                              // again
291	                ap_uint<_WAxi> vec = vec_strm.read();
292	                vec_aligned((scal_char << 3) - 1, (scal_char - offset) << 3) = vec(offset << 3, 0);
293	                vec_reg((scal_char << 3) - 1, offset << 3) = vec((scal_char << 3) - 1, offset << 3);
294	                cnt_r--;
295	            } // else few cases no read again
296	            int n = (i + scal_vec) > nwrite ? (nwrite - i) : scal_vec;
297	            for (int j = 0; j < scal_vec; ++j) {
298	#pragma HLS PIPELINE II = 1
299	                ap_uint<WStrm> r0 = vec_aligned.range(WStrm * (j + 1) - 1, WStrm * j);
300	                if (j < n) {
301	                    r_strm.write((_TStrm)r0);
302	                    e_strm.write(false);
303	                } // end if
304	            }
305	        } // end loop
306	    }
307	
308	    if (!offset) {
309	    // no read
310	    SPLIT_VEC:
311	        int fst_n = scal_vec > nwrite ? nwrite : scal_vec;
312	        for (int j = 0; j < scal_vec; ++j) {
313	#pragma HLS PIPELINE II = 1
314	            ap_uint<WStrm> r0 = vec_reg.range(WStrm * (j + 1) - 1, WStrm * j);
315	            if (j < fst_n) {
316	                r_strm.write((_TStrm)r0);
317	                e_strm.write(false);
318	            }
319	        }
320	
321	        for (int i = scal_vec; i < nwrite; i += scal_vec) {
322	#pragma HLS loop_tripcount min = 1 max = 1
323	#pragma HLS PIPELINE II = scal_vec
324	            ap_uint<_WAxi> vec = vec_strm.read();
325	            int n = (i + scal_vec) > nwrite ? (nwrite - i) : scal_vec;
326	
327	            for (int j = 0; j < scal_vec; ++j) {
328	#pragma HLS PIPELINE II = 1
329	                ap_uint<WStrm> r0 = vec.range(WStrm * (j + 1) - 1, WStrm * j);
330	                if (j < n) {
331	                    r_strm.write((_TStrm)r0);
332	                    e_strm.write(false);
333	                }
334	            }
335	        }
336	    }
337	    e_strm.write(true);
338	}
339	
340	template <int _WAxi, typename _TStrm, int scal_vec>
341	void split_vec_to_aligned(hls::stream<ap_uint<_WAxi> >& vec_strm,
342	                          const int len,
343	                          const int scal_char,
344	                          const int offset,
345	                          hls::stream<_TStrm>& r_strm) {
346	    const int nread = (len + offset + scal_char - 1) / scal_char;
347	    // n read times except the first read, n_read+1 = total read times
348	    int cnt_r = nread - 1;
349	    const int nwrite = (len + sizeof(_TStrm) - 1) / sizeof(_TStrm);
350	    const int WStrm = 8 * sizeof(_TStrm);
351	    // first read is specific
352	    ap_uint<_WAxi> vec_reg = vec_strm.read();
353	    ap_uint<_WAxi> vec_aligned = 0;
354	
355	    if (offset) {
356	    LOOP_SPLIT_VEC_TO_ALIGNED:
357	        for (int i = 0; i < nwrite; i += scal_vec) {
358	#pragma HLS loop_tripcount min = 1 max = 1
359	#pragma HLS PIPELINE II = scal_vec
360	            vec_aligned(((scal_char - offset) << 3) - 1, 0) = vec_reg((scal_char << 3) - 1, offset << 3);
361	            if ((scal_char - offset) < len && (cnt_r != 0)) { // always need read
362	                                                              // again
363	                ap_uint<_WAxi> vec = vec_strm.read();
364	                vec_aligned((scal_char << 3) - 1, (scal_char - offset) << 3) = vec(offset << 3, 0);
365	                vec_reg((scal_char << 3) - 1, offset << 3) = vec((scal_char << 3) - 1, offset << 3);
366	                cnt_r--;
367	            } // else few cases no read again
368	            int n = (i + scal_vec) > nwrite ? (nwrite - i) : scal_vec;
369	            for (int j = 0; j < scal_vec; ++j) {
370	#pragma HLS PIPELINE II = 1
371	                ap_uint<WStrm> r0 = vec_aligned.range(WStrm * (j + 1) - 1, WStrm * j);
372	                if (j < n) {
373	                    r_strm.write((_TStrm)r0);
374	                } // end if
375	            }
376	        } // end loop
377	    }
378	
379	    if (!offset) {
380	    // no read
381	    SPLIT_VEC:
382	        int fst_n = scal_vec > nwrite ? nwrite : scal_vec;
383	        for (int j = 0; j < scal_vec; ++j) {
384	#pragma HLS PIPELINE II = 1
385	            ap_uint<WStrm> r0 = vec_reg.range(WStrm * (j + 1) - 1, WStrm * j);
386	            if (j < fst_n) {
387	                r_strm.write((_TStrm)r0);
388	            }
389	        }
390	
391	        for (int i = scal_vec; i < nwrite; i += scal_vec) {
392	#pragma HLS loop_tripcount min = 1 max = 1
393	#pragma HLS PIPELINE II = scal_vec
394	            ap_uint<_WAxi> vec = vec_strm.read();
395	            int n = (i + scal_vec) > nwrite ? (nwrite - i) : scal_vec;
396	
397	            for (int j = 0; j < scal_vec; ++j) {
398	#pragma HLS PIPELINE II = 1
399	                ap_uint<WStrm> r0 = vec.range(WStrm * (j + 1) - 1, WStrm * j);
400	                if (j < n) {
401	                    r_strm.write((_TStrm)r0);
402	                }
403	            }
404	        }
405	    }
406	}
407	
408	} // namespace details
409	
410	template <int _BurstLen, int _WAxi, typename _TStrm>
411	void axiToStream(ap_uint<_WAxi>* rbuf, const int num, hls::stream<_TStrm>& ostrm, hls::stream<bool>& e_ostrm) {
412	    XF_UTILS_HW_STATIC_ASSERT(_WAxi % sizeof(_TStrm) == 0, "AXI port width is not multiple of stream element width.");
413	    XF_UTILS_HW_STATIC_ASSERT((_WAxi == 8) || (_WAxi == 16) || (_WAxi == 32) || (_WAxi == 64) || (_WAxi == 128) ||
414	                                  (_WAxi == 256) || (_WAxi == 512) || (_WAxi == 1024),
415	                              "AXI port width must be power of 2 and between 8 to 1024.");
416	
417	#pragma HLS DATAFLOW
418	    static const int fifo_depth = _BurstLen * 2;
419	    static const int size0 = sizeof(_TStrm);
420	    static const int scal_vec = _WAxi / (8 * size0);
421	    static const int scal_char = _WAxi / 8;
422	
423	    hls::stream<ap_uint<_WAxi> > vec_strm;
424	#pragma HLS bind_storage variable = vec_strm type = FIFO impl = LUTRAM
425	#pragma HLS STREAM variable = vec_strm depth = fifo_depth
426	
427	    details::read_to_vec<_WAxi, _BurstLen>(rbuf, num, scal_vec, vec_strm);
428	
429	    details::split_vec<_WAxi, _TStrm, scal_vec>(vec_strm, num, 0, ostrm, e_ostrm);
430	}
431	
432	template <int _BurstLen, int _WAxi, typename _TStrm>
433	void axiToCharStream(ap_uint<_WAxi>* rbuf,
434	                     hls::stream<_TStrm>& ostrm,
435	                     hls::stream<bool>& e_ostrm,
436	                     const int len,
437	                     const int offset /* = 0 in decl */) {
438	    XF_UTILS_HW_STATIC_ASSERT(_WAxi % sizeof(_TStrm) == 0, "AXI port width is not multiple of stream element width.");
439	    XF_UTILS_HW_STATIC_ASSERT((_WAxi == 8) || (_WAxi == 16) || (_WAxi == 32) || (_WAxi == 64) || (_WAxi == 128) ||
440	                                  (_WAxi == 256) || (_WAxi == 512) || (_WAxi == 1024),
441	                              "AXI port width must be power of 2 and between 8 to 1024.");
442	#pragma HLS DATAFLOW
443	    static const int fifo_depth = _BurstLen * 2;
444	    static const int size0 = sizeof(_TStrm);
445	    static const int scal_vec = _WAxi / (8 * size0);
446	    static const int scal_char = _WAxi / 8;
447	
448	    hls::stream<ap_uint<_WAxi> > vec_strm;
449	#pragma HLS bind_storage variable = vec_strm type = FIFO impl = LUTRAM
450	#pragma HLS STREAM variable = vec_strm depth = fifo_depth
451	
452	    details::read_to_vec<_WAxi, _BurstLen>(rbuf, len, scal_char, offset, vec_strm);
453	
454	    details::split_vec_to_aligned<_WAxi, _TStrm, scal_vec>(vec_strm, len, scal_char, offset, ostrm, e_ostrm);
455	}
456	
457	template <int _BurstLen, int _WAxi, typename _TStrm>
458	void axiToStream(ap_uint<_WAxi>* rbuf, const int num, hls::stream<_TStrm>& ostrm) {
459	#pragma HLS DATAFLOW
460	    static const int fifo_depth = _BurstLen * 2;
461	    static const int size0 = sizeof(_TStrm);
462	    // static const int size0 = _WAxi / 8;
463	    static const int scal_vec = _WAxi / (8 * size0);
464	    static const int scal_char = _WAxi / 8;
465	
466	    hls::stream<ap_uint<_WAxi> > vec_strm;
467	#pragma HLS bind_storage variable = vec_strm type = FIFO impl = LUTRAM
468	#pragma HLS STREAM variable = vec_strm depth = fifo_depth
469	
470	    details::read_to_vec<_WAxi, _BurstLen>(rbuf, num, scal_vec, vec_strm);
471	
472	    details::split_vec<_WAxi, _TStrm, scal_vec>(vec_strm, num, 0, ostrm);
473	}
