35	/**
36	 * @brief Write elements in burst to AXI master port.
37	 *
38	 * @tparam _BurstLen length of a burst, default is 32.
39	 * @tparam _WAxi     width of axi port.
40	 * @tparam _WStrm    width of input stream.
41	 *
42	 * @param wbuf    output AXI port.
43	 * @param istrm   input stream.
44	 * @param e_istrm end flag for input stream
45	 */
46	template <int _BurstLen = 32, int _WAxi, int _WStrm>
47	void streamToAxi(ap_uint<_WAxi>* wbuf, hls::stream<ap_uint<_WStrm> >& istrm, hls::stream<bool>& e_istrm);
48	} // utils_hw
49	} // common
50	} // xf
