52	namespace xf {
53	namespace common {
54	namespace utils_hw {
55	namespace details {
56	
57	/**
58	 * @brief the template of convert stream width from _WStrm to _WAxi and count
59	 * burst number.
60	 *
61	 * @tparam _WAxi   width of axi port.
62	 * @tparam _WStrm  width of input stream.
63	 * @tparam _BurstLen length of a burst.
64	 *
65	 * @param istrm   input stream.
66	 * @param e_istrm  end flag for input stream
67	 * @param axi_strm stream width is _WAxi
68	 * @param nb_strm  store burst number of each burst
69	 */
70	template <int _WAxi, int _WStrm, int _BurstLen>
71	void countForBurst(hls::stream<ap_uint<_WStrm> >& istrm,
72	                   hls::stream<bool>& e_istrm,
73	                   hls::stream<ap_uint<_WAxi> >& axi_strm,
74	                   hls::stream<ap_uint<8> >& nb_strm) {
75	    const int N = _WAxi / _WStrm;
76	    ap_uint<_WAxi> tmp;
77	    bool isLast;
78	    int nb = 0;
79	    int bs = 0;
80	
81	    isLast = e_istrm.read();
82	doing_loop:
83	    while (!isLast) {
84	#pragma HLS pipeline II = 1
85	        isLast = e_istrm.read();
86	        int offset = bs * _WStrm;
87	        ap_uint<_WStrm> t = istrm.read();
88	        tmp.range(offset + _WStrm - 1, offset) = t(_WStrm - 1, 0);
89	        if (bs == (N - 1)) {
90	            axi_strm.write(tmp);
91	            if (nb == (_BurstLen - 1)) {
92	                nb_strm.write(_BurstLen);
93	                nb = 0;
94	            } else
95	                ++nb;
96	            bs = 0;
97	        } else
98	            ++bs;
99	    }
100	    // not enough one axi
101	    if (bs != 0) {
102	    doing_not_enough:
103	        for (; bs < N; ++bs) {
104	#pragma HLS unroll
105	            int offset = bs * _WStrm;
106	            tmp.range(offset + _WStrm - 1, offset) = 0;
107	        }
108	        axi_strm.write(tmp);
109	        ++nb;
110	    }
111	    if (nb != 0) {
112	        XF_UTILS_HW_ASSERT(nb <= _BurstLen);
113	        nb_strm.write(nb);
114	    }
115	    nb_strm.write(0);
116	}
117	
118	/**
119	 * @brief the template of stream width of _WAxi burst out.
120	 *
121	 * @tparam _WAxi   width of axi port.
122	 * @tparam _WStrm  width of input stream.
123	 * @tparam _BurstLen length of a burst.
124	 *
125	 * @param wbuf AXI master port to write to.
126	 * @param axi_strm stream width is _WAxi
127	 * @param nb_strm  store burst number of each burst
128	 */
129	template <int _WAxi, int _WStrm, int _BurstLen>
130	void burstWrite(ap_uint<_WAxi>* wbuf, hls::stream<ap_uint<_WAxi> >& axi_strm, hls::stream<ap_uint<8> >& nb_strm) {
131	    // write each burst to axi
132	    int total = 0;
133	    ap_uint<_WAxi> tmp;
134	    int n = nb_strm.read();
135	doing_burst:
136	    while (n) {
137	    doing_one_burst:
138	        for (int i = 0; i < n; i++) {
139	#pragma HLS pipeline II = 1
140	            tmp = axi_strm.read();
141	            wbuf[total * _BurstLen + i] = tmp;
142	        }
143	        total++;
144	        n = nb_strm.read();
145	    }
146	}
147	} // details
