149	template <int _BurstLen, int _WAxi, int _WStrm>
150	void streamToAxi(ap_uint<_WAxi>* wbuf, hls::stream<ap_uint<_WStrm> >& istrm, hls::stream<bool>& e_istrm) {
151	    XF_UTILS_HW_STATIC_ASSERT(_WAxi % _WStrm == 0, "AXI port width is not multiple of stream width");
152	    const int fifo_buf = 2 * _BurstLen;
153	
154	#pragma HLS dataflow
155	
156	    hls::stream<ap_uint<_WAxi> > axi_strm;
157	    hls::stream<ap_uint<8> > nb_strm;
158	#pragma HLS stream variable = nb_strm depth = 2
159	#pragma HLS stream variable = axi_strm depth = fifo_buf
160	
161	    details::countForBurst<_WAxi, _WStrm, _BurstLen>(istrm, e_istrm, axi_strm, nb_strm);
162	
163	    details::burstWrite<_WAxi, _WStrm, _BurstLen>(wbuf, axi_strm, nb_strm);
164	}
