137	void streamCombine(hls::stream<ap_uint<_WIn> > istrms[_NStrm],
138	                   hls::stream<bool>& e_istrm,
139	
140	                   hls::stream<ap_uint<_WOut> >& ostrm,
141	                   hls::stream<bool>& e_ostrm,
