154	
155	// comebin_left
156	template <int _WIn, int _NStrm>
157	void streamCombine(hls::stream<ap_uint<_NStrm> >& select_cfg,
158	
159	                   hls::stream<ap_uint<_WIn> > istrms[_NStrm],
160	                   hls::stream<bool>& e_istrm,
161	
162	                   hls::stream<ap_uint<_WIn * _NStrm> >& ostrm,
163	                   hls::stream<bool>& e_ostrm,
164	
165	                   LSBSideT alg) {
166	    bool e = e_istrm.read();
167	    ap_uint<_NStrm> bb = select_cfg.read();
168	    bool b[_NStrm][_NStrm];
169	#pragma HLS array_partition variable = b complete dim = 1
170	    // b record output payload of colum
171	    ap_uint<_WIn * _NStrm> tmp_pld;
172	    ap_uint<_WIn> tmp[_NStrm][_NStrm];
173	#pragma HLS array_partition variable = tmp complete dim = 1
174	
175	loop:
176	    while (!e) {
177	#pragma HLS pipeline II = 1
178	        for (int i = 0; i < _NStrm; i++) {
179	#pragma HLS unroll
180	            tmp[0][i] = istrms[i].read();
181	            b[0][i] = bb[i];
182	        }
183	        for (int k = 0; k < _NStrm - 1; k++) {
184	#pragma HLS unroll
185	            int flag = 0;
186	            for (int j = 0; j < _NStrm; j++) {
187	#pragma HLS unroll
188	                if (b[k][j] == 1 && flag == 0) {
189	                    // if b == 1,column stay the same
190	                    b[k + 1][j] = b[k][j];
191	                    tmp[k + 1][j] = tmp[k][j];
192	                }
193	                if ((b[k][j] == 0 && flag == 0) || (flag == 1)) {
194	                    // if b == 0,columns all on the right side shift one step
195	                    if (j < _NStrm - 1) {
196	                        b[k + 1][j] = b[k][j + 1];
197	                        tmp[k + 1][j] = tmp[k][j + 1];
198	                    }
199	                    // padding zero at the last column
200	                    if (j == _NStrm - 1) {
201	                        b[k + 1][_NStrm - 1] = 0;
202	                        tmp[k + 1][_NStrm - 1] = 0;
203	                    }
204	                    flag = 1;
205	                }
206	            }
207	        }
208	        for (int i = 0; i < _NStrm; i++) {
209	#pragma HLS unroll
210	            tmp_pld(_WIn * (i + 1) - 1, _WIn * i) = tmp[_NStrm - 1][i];
211	        }
212	        {
213	            ostrm.write(tmp_pld);
214	            e_ostrm.write(0);
215	        }
216	        e = e_istrm.read();
217	    }
218	    e_ostrm.write(1);
219	}
220	
221	// combine right
222	template <int _WIn, int _NStrm>
223	void streamCombine(hls::stream<ap_uint<_NStrm> >& select_cfg,
224	
225	                   hls::stream<ap_uint<_WIn> > istrms[_NStrm],
226	                   hls::stream<bool>& e_istrm,
227	
228	                   hls::stream<ap_uint<_WIn * _NStrm> >& ostrm,
229	                   hls::stream<bool>& e_ostrm,
230	
231	                   MSBSideT alg) {
232	    bool e = e_istrm.read();
233	    ap_uint<_NStrm> bb = select_cfg.read();
234	    bool b[_NStrm][_NStrm];
235	#pragma HLS array_partition variable = b complete dim = 1
236	    // b record output payload of colum
237	    ap_uint<_WIn * _NStrm> tmp_pld;
238	    ap_uint<_WIn> tmp[_NStrm][_NStrm];
239	#pragma HLS array_partition variable = tmp complete dim = 1
240	
241	loop:
242	    while (!e) {
243	#pragma HLS pipeline II = 1
244	        for (int i = 0; i < _NStrm; i++) {
245	#pragma HLS unroll
246	            tmp[0][i] = istrms[i].read();
247	            b[0][i] = bb[i];
248	        }
249	        for (int k = 0; k < _NStrm - 1; k++) {
250	#pragma HLS unroll
251	            int flag = 0;
252	            for (int j = 0; j < _NStrm; j++) {
253	#pragma HLS unroll
254	                if (b[k][j] == 1 && flag == 0) {
255	                    // if b == 1,column stay the same
256	                    b[k + 1][j] = b[k][j];
257	                    tmp[k + 1][j] = tmp[k][j];
258	                }
259	                if ((b[k][j] == 0 && flag == 0) || (flag == 1)) {
260	                    // if b == 0,columns all on the right side shift one step
261	                    if (j < _NStrm - 1) {
262	                        b[k + 1][j] = b[k][j + 1];
263	                        tmp[k + 1][j] = tmp[k][j + 1];
264	                    }
265	                    // padding zero at the last column
266	                    if (j == _NStrm - 1) {
267	                        b[k + 1][_NStrm - 1] = 0;
268	                        tmp[k + 1][_NStrm - 1] = 0;
269	                    }
270	                    flag = 1;
271	                }
272	            }
273	        }
274	        for (int i = 0; i < _NStrm; i++) {
275	#pragma HLS unroll
276	            tmp_pld(_WIn * (i + 1) - 1, _WIn * i) = tmp[_NStrm - 1][_NStrm - i - 1];
277	        }
278	        {
279	            ostrm.write(tmp_pld);
280	            e_ostrm.write(0);
281	        }
282	        e = e_istrm.read();
283	    }
284	    e_ostrm.write(1);
285	}
286	
287	template <int _WIn, int _WOut, int _NStrm>
288	void streamCombine(hls::stream<ap_uint<_WIn> > istrms[_NStrm],
289	                   hls::stream<bool>& e_istrm,
290	                   hls::stream<ap_uint<_WOut> >& ostrm,
291	                   hls::stream<bool>& e_ostrm,
292	                   LSBSideT alg) {
293	    /*
294	     * stream
295	     *   [0]      0    4    8
296	     *   [1]      1    5    9
297	     *   [2]      2    6    a
298	     *   [3]      3    7    b
299	     *
300	     * output  3210 7654 ba98
301	     */
302	
303	    const int max = _WIn * _NStrm > _WOut ? _WIn * _NStrm : _WOut;
304	    bool last = e_istrm.read();
305	    while (!last) {
306	#pragma HLS pipeline II = 1
307	        last = e_istrm.read();
308	        ap_uint<max> cmb = 0;
309	        for (int i = 0; i < _NStrm; ++i) {
310	#pragma HLS unroll
311	            cmb.range((i + 1) * _WIn - 1, i * _WIn) = istrms[i].read();
312	        }
313	        ap_uint<_WOut> o_cmb = cmb;
314	        ostrm.write(o_cmb);
315	        e_ostrm.write(false);
316	    }
317	    e_ostrm.write(true);
318	}
319	
320	template <int _WIn, int _WOut, int _NStrm>
321	void streamCombine(hls::stream<ap_uint<_WIn> > istrms[_NStrm],
322	                   hls::stream<bool>& e_istrm,
323	                   hls::stream<ap_uint<_WOut> >& ostrm,
324	                   hls::stream<bool>& e_ostrm,
325	                   MSBSideT alg) {
326	    /*
327	     * stream
328	     *   [0]      0    4   8
329	     *   [1]      1    5   9
330	     *   [2]      2    6   a
331	     *   [3]      3    7   b
332	     *
333	     * output  0123 4567 89ab
334	     */
335	
336	    const int max = _WIn * _NStrm > _WOut ? _WIn * _NStrm : _WOut;
337	    const int df = _WOut - _WIn * _NStrm;
338	    const int rdf = df < 0 ? (-df) : df;
339	    const int w = _WIn * _NStrm;
340	    bool last = e_istrm.read();
341	    while (!last) {
342	#pragma HLS pipeline II = 1
343	        last = e_istrm.read();
344	        ap_uint<max> cmb = 0;
345	        for (int i = 0, j = _NStrm - 1; i < _NStrm; ++i, --j) {
346	#pragma HLS unroll
347	            cmb.range((j + 1) * _WIn - 1, j * _WIn) = istrms[i].read();
348	        }
349	        ap_uint<_WOut> o_cmb = (df >= 0) ? (cmb << df) : (cmb >> rdf);
350	        ostrm.write(o_cmb);
351	        e_ostrm.write(false);
352	    }
353	    e_ostrm.write(true);
354	}
355	
356	} // utils_hw
357	} // common
358	} // xf
359	
360	#endif // XF_UTILS_HW_STREAM_COMBINE_H
