void streamCombine(hls::stream<ap_uint<_NStrm> >& select_cfg,

                   hls::stream<ap_uint<_WIn> > istrms[_NStrm],
                   hls::stream<bool>& e_istrm,

                   hls::stream<ap_uint<_WIn * _NStrm> >& ostrm,
