70	 * pack multiple elements to one row. If it is beyond 72-bits, multiple URAMs
71	 * will be used to ensure elements can be fetched in one cycle.
72	 *
73	 * To make the cache really functional, HLS needs to be instructed to ignore
74	 * inter-iteration dependencies on ``blocks`` of ``UramArray`` objects.
75	 * Please refer to the test of this module for an example.
76	 *
77	 * \rst
78	 * .. ATTENTION::
79	 *     This module requires HLS 2019.1 or above.
80	 * \endrst
81	 *
82	 * @tparam _WData  the width of every element.
83	 * @tparam _NData  the number of elements in the array.
84	 * @tparam _NCache the number of cache.
85	 */
86	template <int _WData, int _NData, int _NCache>
87	class UramArray {
88	   public:
89	    UramArray() {
90	#pragma HLS inline
91	#pragma HLS bind_storage variable = blocks type = RAM_2P impl = URAM
92	#pragma HLS array_partition variable = blocks complete dim = 1
93	#pragma HLS array_partition variable = blocks complete dim = 2
94	#pragma HLS array_partition variable = _index complete dim = 1
95	#pragma HLS array_partition variable = _state complete dim = 1
96	        initialize();
97	    }
98	
99	   private:
100	    void initialize() {
101	#ifndef __SYNTHESIS__
102	        for (int i = 0; i < _num_uram_x; i++) {
103	            for (int j = 0; j < _num_uram_y; j++) {
104	                blocks[i][j] = (ap_uint<72>*)malloc(sizeof(ap_uint<72>) * 4096);
105	            }
106	        }
107	#endif
108	        for (int i = 0; i < _NCache; i++) {
109	#pragma HLS unroll
110	            _index[i] = -1;
111	            _state[i] = 0;
112	        }
113	    }
114	
115	   public:
116	    ~UramArray() {
117	#ifndef __SYNTHESIS__
118	        for (int i = 0; i < _num_uram_x; i++) {
119	            for (int j = 0; j < _num_uram_y; j++) {
120	                free(blocks[i][j]);
121	            }
122	        }
123	#endif
124	    }
125	
126	    /// @brief  initialization for uram.
127	    /// @param  d value for initialization.
128	    /// @return number of block which had been initialize.
129	    int memSet(const ap_uint<_WData>& d);
130	
131	    /// @brief write to uram.
132	    /// @param index the index which you want to write.
133	    /// @param d     the value what you want to write.
134	    void write(int index, const ap_uint<_WData>& d);
135	
136	    /// @brief  read from uram.
137	    /// @param  index the index which you want to read.
138	    /// @return value you had read.
139	    ap_uint<_WData> read(int index);
140	
141	   private:
142	    /// number elements per line, used with _WData<=72. For example, when _WData =
143	    /// 16, _elem_per_line is 4.
144	    static const int _elem_per_line;
145	
146	    /// piece of block using one time.
147	    static const int _num_parallel_block;
148	
149	    /// index numbers of one block.
150	    static const int _elem_per_block;
151	
152	    /// the numbers of need to access.
153	    static const int _num_uram_block;
154	    static const int _num_uram_x;
155	    static const int _num_uram_y;
156	
157	    /// the cache for saving latest index.
158	    int _index[_NCache];
159	
160	    /// the cache for saving latest value.
161	    ap_uint<_WData> _state[_NCache];
162	
163	   public:
164	// XXX this has to be public, otherwise `depencency false` cannot be
165	// specified.
166	#ifndef __SYNTHESIS__
167	    ap_uint<72>* blocks[details::need_num<_WData, _NData>::value_x][details::need_num<_WData, _NData>::value_y];
168	#else
169	    ap_uint<72> blocks[details::need_num<_WData, _NData>::value_x][details::need_num<_WData, _NData>::value_y][4096];
