195	template <int _WData, int _NData, int _NCache>
196	int UramArray<_WData, _NData, _NCache>::memSet(const ap_uint<_WData>& d) {
197	    if (_num_uram_block == 0) return 0;
198	
199	    ap_uint<72> t;
200	l_init_value:
201	    for (int i = 0; i < 4096; i++) {
202	#pragma HLS PIPELINE II = 1
203	        for (int nx = 0; nx < _num_uram_x; nx++) {
204	#pragma HLS unroll
205	            for (int ny = 0; ny < _num_uram_y; ny++) {
206	#pragma HLS unroll
207	                if (_WData <= 72) {
208	                    for (int j = 0; j < _elem_per_line; j++) {
209	#pragma HLS unroll
210	                        t(j * _WData + _WData - 1, j * _WData) = d(_WData - 1, 0);
211	                    }
212	                    blocks[nx][ny][i] = t;
213	                } else {
214	                    int begin = ny * 72;
215	                    if (ny == (_num_parallel_block - 1))
216	                        blocks[nx][ny][i] = d(_WData - 1, begin);
217	                    else
218	                        blocks[nx][ny][i] = d(begin + 71, begin);
219	                }
220	            }
221	        }
222	    }
223	
224	// update d for cache
225	init_cache:
226	    for (int i = 0; i < _NCache; i++) {
227	#pragma HLS unroll
228	        _state[i] = d;
229	        _index[i] = 0;
230	    }
231	
232	    return _num_uram_block;
233	}
234	
235	template <int _WData, int _NData, int _NCache>
236	void UramArray<_WData, _NData, _NCache>::write(int index, const ap_uint<_WData>& d) {
237	#pragma HLS inline
238	    int div_block = 0, div_index = 0;
239	    int dec_block = 0, dec, begin;
240	
241	Write_Inner:
242	    for (int i = 0; i < _num_parallel_block; i++) {
243	        if (_WData <= 72) {
244	            div_block = index / _elem_per_block;
245	            dec_block = index % _elem_per_block;
246	            div_index = dec_block / _elem_per_line;
247	            dec = dec_block % _elem_per_line;
248	            begin = dec * _WData;
249	            ap_uint<72> tmp = blocks[div_block][0][div_index];
250	            tmp.range(begin + _WData - 1, begin) = d;
251	            blocks[div_block][0][div_index] = tmp;
252	        } else {
253	            div_block = index / 4096;
254	            dec_block = index % 4096;
255	            begin = i * 72;
256	            if (i == (_num_parallel_block - 1))
257	                blocks[div_block][i][dec_block] = d.range(_WData - 1, begin);
258	            else
259	                blocks[div_block][i][dec_block] = d.range(begin + 71, begin);
260	        }
261	    }
262	
263	Write_Cache:
264	    for (int i = _NCache - 1; i >= 1; i--) {
265	        _state[i] = _state[i - 1];
266	        _index[i] = _index[i - 1];
267	    }
268	    _state[0] = d;
269	    _index[0] = index;
270	}
271	
272	template <int _WData, int _NData, int _NCache>
273	ap_uint<_WData> UramArray<_WData, _NData, _NCache>::read(int index) {
274	#pragma HLS inline
275	    ap_uint<_WData> value;
276	    int div_block = 0, div_index = 0;
277	    int dec_block = 0, dec, begin;
278	
279	Read_Cache:
280	    for (int i = 0; i < _NCache; i++) {
281	        if (index == _index[i]) {
282	            value = _state[i];
283	            return value;
284	        }
285	    }
286	
287	Read_Inner:
288	    for (int i = 0; i < _num_parallel_block; i++) {
289	        if (_WData <= 72) {
290	            div_block = index / _elem_per_block;
291	            dec_block = index % _elem_per_block;
292	            div_index = dec_block / _elem_per_line;
293	            dec = dec_block % _elem_per_line;
294	            begin = dec * _WData;
295	            ap_uint<72> tmp = blocks[div_block][0][div_index];
296	            value = tmp.range(begin + _WData - 1, begin);
297	        } else {
298	            div_block = index / 4096;
299	            dec_block = index % 4096;
300	            begin = i * 72;
301	
302	            if (i == (_num_parallel_block - 1))
303	                value.range(_WData - 1, begin) = blocks[div_block][i][dec_block];
304	            else {
305	                value.range(begin + 71, begin) = blocks[div_block][i][dec_block];
306	            }
307	        }
308	    }
309	    return value;
310	}
