326	            ap_uint<dataOneLine> validTmp;
327	            if (k01 == validAddrQue[0]) {
328	                validTmp = validQue[0];
329	            } else if (k01 == validAddrQue[1]) {
330	                validTmp = validQue[1];
331	            } else if (k01 == validAddrQue[2]) {
332	                validTmp = validQue[2];
333	            } else if (k01 == validAddrQue[3]) {
334	                validTmp = validQue[3];
335	            } else {
336	                validTmp = valid[k20][k10];
337	            }
338	            ap_uint<1> validBool = validTmp[k00]; // to check
339	            ap_uint<512> tmpV;
340	            ap_uint<addrWidth> address;
341	            ap_uint<addrWidth> addrTmp;
342	            if (k01 == addrAddrQue[0]) {
343	                addrTmp = addrQue[0];
344	            } else if (k01 == addrAddrQue[1]) {
345	                addrTmp = addrQue[1];
346	            } else if (k01 == addrAddrQue[2]) {
347	                addrTmp = addrQue[2];
348	            } else if (k01 == addrAddrQue[3]) {
349	                addrTmp = addrQue[3];
350	            } else {
351	                addrTmp = onChipAddr[k20][k10];
352	            }
353	            address = addrTmp;
354	            if ((validBool == 1) && (address == k30)) {
355	                if (k01 == ramAddrQue[0]) {
356	                    tmpV = pingQue[0];
357	                } else if (k01 == ramAddrQue[1]) {
358	                    tmpV = pingQue[1];
359	                } else if (k01 == ramAddrQue[2]) {
360	                    tmpV = pingQue[2];
