405	    /// @brief readOnly function that index two off-chip buffers without end flags. Both of the buffers should be
406	    /// indexed in exactly the same behaviour.
407	    /// @param cnt			The number of access to the memory
408	    /// @param ddrMem0		The pointer for the first off chip memory
409	    /// @param ddrMem1		The pointer for the second off chip memory
410	    /// @param addrStrm		The read address should be sent from this stream
411	    /// @param data0Strm	The data loaded from the first off chip memory
412	    /// @param data1Strm	The data loaded from the second off chip memory
413	    void readOnly(int cnt,
414	                  ap_uint<512>* ddrMem0,
415	                  ap_uint<512>* ddrMem1,
416	                  hls::stream<ap_uint<32> >& addrStrm,
417	                  hls::stream<T>& data0Strm,
418	                  hls::stream<T>& data1Strm) {
419	#pragma HLS inline off
420	
421	        ap_uint<dataOneLine> validCnt;
422	        for (int i = 0; i < dataOneLine; ++i) {
423	#pragma HLS loop_tripcount min = 8 avg = 8 max = 8
424	#pragma HLS pipeline II = 1
425	            validCnt[i] = 1;
426	        }
427	        const int size = sizeof(T) * 8;
428	
429	        ap_uint<addrWidth + 1> addrQue[4] = {-1, -1, -1, -1};
430	        ap_uint<512> pingQue[4] = {0, 0, 0, 0};
431	        ap_uint<512> cntQue[4] = {0, 0, 0, 0};
432	        ap_uint<dataOneLine> validQue[4] = {0, 0, 0, 0};
433	        int validAddrQue[4] = {-1, -1, -1, -1};
434	        int addrAddrQue[4] = {-1, -1, -1, -1};
435	        int ramAddrQue[4] = {-1, -1, -1, -1};
436	#pragma HLS array_partition variable = validQue complete dim = 1
437	#pragma HLS array_partition variable = validAddrQue complete dim = 1
438	#pragma HLS array_partition variable = cntQue complete dim = 1
439	#pragma HLS array_partition variable = ramAddrQue complete dim = 1
440	#pragma HLS array_partition variable = pingQue complete dim = 1
441	#pragma HLS array_partition variable = addrQue complete dim = 1
442	#pragma HLS array_partition variable = addrAddrQue complete dim = 1
443	
444	        for (int i = 0; i < cnt; ++i) {
445	#pragma HLS loop_tripcount min = 16500000 avg = 16500000 max = 16500000
446	#pragma HLS pipeline II = 1
447	#pragma HLS DEPENDENCE variable = valid type = inter direction = RAW distance = 1 true
448	#pragma HLS DEPENDENCE variable = onChipRam0 type = inter direction = RAW distance = 1 true
449	#pragma HLS DEPENDENCE variable = onChipRam1 type = inter direction = RAW distance = 1 true
450	#pragma HLS DEPENDENCE variable = onChipAddr type = inter direction = RAW distance = 1 true
451	            int index = addrStrm.read();
452	            int k00 = index % dataOneLine;
453	            int k01 = index / dataOneLine;
454	            int k10 = k01 % groupRamPart;
455	            int k11 = k01 / groupRamPart;
456	            int k20 = k11 % ramRow;
457	            int k21 = k11 / ramRow;
458	            int k30 = k21;
459	
460	            ap_uint<dataOneLine> validTmp;
461	            if (k01 == validAddrQue[0]) {
462	                validTmp = validQue[0];
463	            } else if (k01 == validAddrQue[1]) {
464	                validTmp = validQue[1];
465	            } else if (k01 == validAddrQue[2]) {
466	                validTmp = validQue[2];
467	            } else if (k01 == validAddrQue[3]) {
468	                validTmp = validQue[3];
469	            } else {
470	                validTmp = valid[k20][k10];
471	            }
472	            ap_uint<1> validBool = validTmp[k00]; // to check
473	            ap_uint<512> tmpV, tmpC;
474	            ap_uint<addrWidth> address;
475	            ap_uint<addrWidth> addrTmp;
476	            if (k01 == addrAddrQue[0]) {
477	                addrTmp = addrQue[0];
478	            } else if (k01 == addrAddrQue[1]) {
479	                addrTmp = addrQue[1];
480	            } else if (k01 == addrAddrQue[2]) {
481	                addrTmp = addrQue[2];
482	            } else if (k01 == addrAddrQue[3]) {
483	                addrTmp = addrQue[3];
484	            } else {
485	                addrTmp = onChipAddr[k20][k10];
486	            }
