506	                tmpV = ddrMem0[k01];
507	                tmpC = ddrMem1[k01];
508	                onChipRam0[k20][k10] = tmpV;
509	                onChipRam1[k20][k10] = tmpC;
510	                pingQue[3] = pingQue[2];
511	                pingQue[2] = pingQue[1];
512	                pingQue[1] = pingQue[0];
513	                pingQue[0] = tmpV;
514	                cntQue[3] = cntQue[2];
515	                cntQue[2] = cntQue[1];
516	                cntQue[1] = cntQue[0];
517	                cntQue[0] = tmpC;
518	                ramAddrQue[3] = ramAddrQue[2];
519	                ramAddrQue[2] = ramAddrQue[1];
520	                ramAddrQue[1] = ramAddrQue[0];
521	                ramAddrQue[0] = k01;
522	                ap_uint<addrWidth> tAddr = (ap_uint<addrWidth>)k30;
523	                addrTmp = tAddr;
524	                onChipAddr[k20][k10] = addrTmp;
525	                addrQue[3] = addrQue[2];
526	                addrQue[2] = addrQue[1];
527	                addrQue[1] = addrQue[0];
528	                addrQue[0] = addrTmp;
529	                addrAddrQue[3] = addrAddrQue[2];
530	                addrAddrQue[2] = addrAddrQue[1];
531	                addrAddrQue[1] = addrAddrQue[0];
532	                addrAddrQue[0] = k01;
533	            }
534	            if (validBool == 0) {
535	                validTmp = validCnt;
536	                valid[k20][k10] = validTmp;
537	                validQue[3] = validQue[2];
538	                validQue[2] = validQue[1];
539	                validQue[1] = validQue[0];
540	                validQue[0] = validTmp;
541	                validAddrQue[3] = validAddrQue[2];
542	                validAddrQue[2] = validAddrQue[1];
