590	#pragma HLS array_partition variable = cntQue complete dim = 1
591	#pragma HLS array_partition variable = ramAddrQue complete dim = 1
592	#pragma HLS array_partition variable = pingQue complete dim = 1
593	#pragma HLS array_partition variable = addrQue complete dim = 1
594	#pragma HLS array_partition variable = addrAddrQue complete dim = 1
595	
596	        bool e = e_addrStrm.read();
