598	        while (!e) {
599	#pragma HLS loop_tripcount min = 16500000 avg = 16500000 max = 16500000
600	#pragma HLS pipeline II = 1
601	#pragma HLS DEPENDENCE variable = valid type = inter direction = RAW distance = 1 true
602	#pragma HLS DEPENDENCE variable = onChipRam0 type = inter direction = RAW distance = 1 true
603	#pragma HLS DEPENDENCE variable = onChipRam1 type = inter direction = RAW distance = 1 true
604	#pragma HLS DEPENDENCE variable = onChipAddr type = inter direction = RAW distance = 1 true
605	            e = e_addrStrm.read();
606	
