635	                addrTmp = addrQue[1];
636	            } else if (k01 == addrAddrQue[2]) {
637	                addrTmp = addrQue[2];
638	            } else if (k01 == addrAddrQue[3]) {
639	                addrTmp = addrQue[3];
640	            } else {
641	                addrTmp = onChipAddr[k20][k10];
642	            }
643	            address = addrTmp;
644	            if ((validBool == 1) && (address == k30)) {
645	                if (k01 == ramAddrQue[0]) {
646	                    tmpV = pingQue[0];
647	                    tmpC = cntQue[0];
648	                } else if (k01 == ramAddrQue[1]) {
649	                    tmpV = pingQue[1];
650	                    tmpC = cntQue[1];
651	                } else if (k01 == ramAddrQue[2]) {
652	                    tmpV = pingQue[2];
653	                    tmpC = cntQue[2];
654	                } else if (k01 == ramAddrQue[3]) {
655	                    tmpV = pingQue[3];
656	                    tmpC = cntQue[3];
657	                } else {
658	                    tmpV = onChipRam0[k20][k10];
659	                    tmpC = onChipRam1[k20][k10];
660	                }
661	            } else {
662	                tmpV = ddrMem0[k01];
663	                tmpC = ddrMem1[k01];
664	                onChipRam0[k20][k10] = tmpV;
665	                onChipRam1[k20][k10] = tmpC;
666	                pingQue[3] = pingQue[2];
667	                pingQue[2] = pingQue[1];
668	                pingQue[1] = pingQue[0];
669	                pingQue[0] = tmpV;
670	                cntQue[3] = cntQue[2];
671	                cntQue[2] = cntQue[1];
672	                cntQue[1] = cntQue[0];
673	                cntQue[0] = tmpC;
674	                ramAddrQue[3] = ramAddrQue[2];
675	                ramAddrQue[2] = ramAddrQue[1];
676	                ramAddrQue[1] = ramAddrQue[0];
677	                ramAddrQue[0] = k01;
